import json, os, glob
from collections import Counter

SESS = r"D:\repository\skills\dsh\langgraph-orchestrator\.sessions"

# planner 作为 execute 工具时的完成 token 分布，作为“它在干什么”的代理指标
comp = []
for p in glob.glob(os.path.join(SESS, "*.costs.jsonl")):
    with open(p, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if r.get("role") == "execute" and r.get("tool") == "planner":
                u = r.get("usage") or {}
                c = u.get("completion_tokens")
                if c is not None:
                    comp.append((c, r.get("elapsed"), os.path.basename(p).replace(".costs.jsonl","")[:12]))

comp.sort()
print("planner-as-execute rows with usage:", len(comp))
if comp:
    vals = [c for c, _, _ in comp]
    print("min=%d max=%d mean=%.0f median=%d" % (min(vals), max(vals), sum(vals)/len(vals), vals[len(vals)//2]))
    # 分桶
    buckets = Counter()
    for c in vals:
        if c < 100: buckets["<100 (寒暄/极短)"] += 1
        elif c < 500: buckets["100-500 (短答)"] += 1
        elif c < 2000: buckets["500-2k (中等解答)"] += 1
        else: buckets[">=2k (长文/代码)"] += 1
    print("\n=== completion token 分桶 ===")
    for k, v in buckets.items():
        print("  %-24s %3d  (%.0f%%)" % (k, v, 100.0*v/len(vals)))
    print("\n=== 前 10 条明细 (tokens, elapsed, session) ===")
    for c, el, s in comp[-10:]:
        print("  %6d  %8s  %s" % (c, el, s))

import json, os, glob
from collections import defaultdict

SESS = r"D:\repository\skills\dsh\langgraph-orchestrator\.sessions"

stat = defaultdict(list)
for p in glob.glob(os.path.join(SESS, "*.costs.jsonl")):
    with open(p, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                r = json.loads(line)
            except json.JSONDecodeError:
                continue
            if r.get("role") != "execute":
                continue
            u = r.get("usage") or {}
            c = u.get("completion_tokens")
            if c is None:
                continue
            stat[r.get("tool") or "-"].append(c)

print("%-24s %4s %8s %8s %8s" % ("tool", "n", "median", "mean", "max"))
for tool, vals in sorted(stat.items(), key=lambda x: -len(x[1])):
    vals.sort()
    print("%-24s %4d %8d %8.0f %8d" % (
        tool, len(vals), vals[len(vals)//2], sum(vals)/len(vals), max(vals)))
